create extension if not exists "uuid-ossp";
create table if not exists public.shops(id text primary key,name text not null,area text not null,x_handle text,x_user_id text,priority boolean default false,valid_default text default '7日間',genres text[] default '{}',created_at timestamptz default now());
create table if not exists public.cards(id uuid primary key default uuid_generate_v4(),tcg_type text not null,card_name text not null,card_number text,rarity text,set_name text,variant text,image_url text,language text default 'ja',created_at timestamptz default now());
create table if not exists public.card_aliases(id uuid primary key default uuid_generate_v4(),card_id uuid references public.cards(id) on delete cascade,alias text not null,created_at timestamptz default now());
create table if not exists public.buy_prices(id uuid primary key default uuid_generate_v4(),card_name text not null,card_number text,tcg_type text not null,shop_id text references public.shops(id) on delete set null,price_yen integer not null,source text not null,source_url text,published_at date,valid_until timestamptz,valid_label text,confidence numeric,approved boolean default true,created_at timestamptz default now());
create table if not exists public.user_items(id uuid primary key default uuid_generate_v4(),user_id uuid,card_name text not null,card_number text,quantity integer not null default 1,purchase_price_yen integer not null default 0,condition text,memo text,created_at timestamptz default now());
create table if not exists public.import_logs(id uuid primary key default uuid_generate_v4(),shop_id text references public.shops(id) on delete set null,added_count integer default 0,raw_text text,created_at timestamptz default now());
create table if not exists public.x_posts(id text primary key,shop_id text references public.shops(id) on delete cascade,text text,source_url text,posted_at timestamptz,has_media boolean default false,processed boolean default false,created_at timestamptz default now());
insert into public.shops(id,name,area,x_handle,priority,valid_default,genres) values ('magiNagoya','magi名古屋PARCO店','大須・栄','@magiNagoya',true,'当日限り',array['ポケカ','ワンピース','遊戯王']),('osuA','大須サンプルカード店','大須・栄','@sample_osu',false,'7日間',array['ポケカ','BOX']),('okazakiA','岡崎サンプルトレカ','岡崎','@sample_okazaki',false,'7日間',array['ポケカ','ワンピース']),('anjoA','安城・刈谷サンプル店','安城・刈谷','@sample_anjo',false,'7日間',array['ポケカ','ユニアリ']) on conflict(id) do nothing;
